import type { PlayerState,StorageLike } from '../types/state.js';import{loadState,saveState}from'./storage.js';export type StoreListener=(state:PlayerState)=>void;export class Store{private state:PlayerState;private readonly listeners=new Set<StoreListener>();constructor(private readonly storage:StorageLike){this.state=loadState(storage)}get():PlayerState{return this.state}update(mutator:(state:PlayerState)=>void):PlayerState{mutator(this.state);this.state=saveState(this.storage,this.state);this.listeners.forEach(listener=>listener(this.state));return this.state}replace(state:PlayerState):void{this.state=saveState(this.storage,state);this.listeners.forEach(listener=>listener(this.state))}subscribe(listener:StoreListener):()=>void{this.listeners.add(listener);return()=>this.listeners.delete(listener)}}
