import type{MatchState,PlayerEntity,NormalizedInput}from'../../types/game.js';import{GAMEPLAY}from'../config.js';import{burstForce,isPerfectDash,pulseForce}from'./AbilityMath.js';import type{Sfx}from'../../audio/Sfx.js';export interface FeedbackPort{combat(text:string,color?:string,duration?:number):void}export class AbilitySystem{constructor(private readonly game:()=>MatchState|null,private readonly sfx:Sfx,private readonly feedback:FeedbackPort){}dash(player:PlayerEntity,input:NormalizedInput):boolean{const game=this.game();if(!game||game.phase!=='play'||player.dashCd>0)return false;let{x,y}=input,length=Math.hypot(x,y);if(length<.1){x=Math.cos(player.face);y=Math.sin(player.face);length=1}player.vx+=x/length*GAMEPLAY.dashImpulse;player.vy+=y/length*GAMEPLAY.dashImpulse;player.dashCd=GAMEPLAY.dashCooldown;player.dashActive=GAMEPLAY.dashActive;player.perfectConsumed=false;this.spawnBurst(player.x,player.y,player.color,14,5);this.spawnRing(player.x,player.y,player.color,18,70,.22);if(!player.ai){this.sfx.play('dash');this.sfx.vibrate(18)}return true}pulse(player:PlayerEntity):boolean{const game=this.game();if(!game||game.phase!=='play'||player.pulseCd>0)return false;player.pulseCd=GAMEPLAY.pulseCooldown;const dx=game.ball.x-player.x,dy=game.ball.y-player.y,distance=Math.hypot(dx,dy),combo=player.dashActive>0,force=pulseForce(distance,player.polarity,combo),color=player.polarity===1?'#59f5ff':'#ff71c6';this.spawnRing(player.x,player.y,color,28,GAMEPLAY.pulseRange,.34);this.spawnBurst(player.x,player.y,color,12,3);if(force!==0&&distance>1){game.ball.vx+=dx/distance*force;game.ball.vy+=dy/distance*force;player.flux=Math.min(100,player.flux+11+Math.abs(force)*.8+(combo?5:0));game.shake=Math.max(game.shake,combo?6:3);if(!player.ai){this.feedback.combat(combo?'DASH + PULSE':'PULSE',color,320);this.sfx.vibrate(combo?20:12)}}if(!player.ai)this.sfx.play(player.polarity===1?'pulsePush':'pulsePull');return true}burst(player:PlayerEntity):boolean{const game=this.game();if(!game||game.phase!=='play'||player.flux<100)return false;player.flux=0;const dx=game.ball.x-player.x,dy=game.ball.y-player.y,distance=Math.hypot(dx,dy)||1,force=burstForce(distance);if(force>0){game.ball.vx+=dx/distance*force;game.ball.vy+=dy/distance*force}game.shake=Math.max(game.shake,18);game.flash=Math.max(game.flash,.7);game.freeze=Math.max(game.freeze,.075);this.spawnRing(player.x,player.y,'#fff',34,GAMEPLAY.burstRange,.48);this.spawnRing(player.x,player.y,'#9a78ff',20,GAMEPLAY.burstRange*.78,.55);this.spawnBurst(player.x,player.y,'#c6b5ff',65,12);this.feedback.combat('RIFT BURST','#fff',650);if(!player.ai){this.sfx.play('burst');this.sfx.vibrate(55)}return true}collision(player:PlayerEntity,power:number):boolean{const game=this.game();if(!game)return false;const ball=game.ball,dx=ball.x-player.x,dy=ball.y-player.y,distance=Math.hypot(dx,dy),minimum=player.r+ball.r;if(!(distance<minimum&&distance>0))return false;const nx=dx/distance,ny=dy/distance,overlap=minimum-distance;ball.x+=nx*overlap;ball.y+=ny*overlap;const relative=(player.vx-ball.vx)*nx+(player.vy-ball.vy)*ny;let impulse=(3.9+Math.max(0,relative)*1.12)*power;const perfect=isPerfectDash(player.dashActive,player.perfectConsumed,distance,minimum);if(perfect){impulse*=GAMEPLAY.perfectDashMultiplier;player.perfectConsumed=true;player.flux=Math.min(100,player.flux+GAMEPLAY.perfectDashFlux);game.freeze=Math.max(game.freeze,.055);game.shake=Math.max(game.shake,12);game.flash=Math.max(game.flash,.36);this.spawnRing(ball.x,ball.y,'#fff',16,135,.3);this.spawnBurst(ball.x,ball.y,'#fff',28,9);if(!player.ai){this.feedback.combat('PERFECT DASH','#6cffad',620);this.sfx.play('perfect');this.sfx.vibrate(32)}}ball.vx+=nx*impulse;ball.vy+=ny*impulse;const tx=-ny,ty=nx,tangent=(player.vx*tx+player.vy*ty)*.12;ball.vx+=tx*tangent;ball.vy+=ty*tangent;player.flux=Math.min(100,player.flux+(perfect?8:4));if(game.hitSfxCd<=0){this.sfx.play(perfect?'perfect':'hit');game.hitSfxCd=.05}game.shake=Math.max(game.shake,perfect?12:Math.min(6,Math.abs(relative)*.6));return perfect}spawnRing(x:number,y:number,color:string,start=20,end=180,life=.35):void{const game=this.game();if(game)game.rings.push({x,y,color,start,end,life,maxLife:life})}spawnBurst(x:number,y:number,color:string,count=18,speed=6):void{const game=this.game();if(!game)return;for(let i=0;i<count;i+=1){const angle=Math.random()*Math.PI*2,velocity=(.35+Math.random()*.65)*speed;game.particles.push({x,y,vx:Math.cos(angle)*velocity,vy:Math.sin(angle)*velocity,life:.25+Math.random()*.35,maxLife:.6,size:1.5+Math.random()*3,color})}}}
