import type{GameplayConfig}from'../../types/game.js';import{GAMEPLAY}from'../config.js';export function pulseForce(distance:number,polarity:1|-1=1,combo=false,config:GameplayConfig=GAMEPLAY):number{if(!Number.isFinite(distance)||distance<=0||distance>=config.pulseRange)return 0;const t=1-distance/config.pulseRange,curve=t*t*(3-2*t),force=config.pulseMinForce+(config.pulseMaxForce-config.pulseMinForce)*curve;return force*(combo?config.pulseComboMultiplier:1)*polarity}export function burstForce(distance:number,config:GameplayConfig=GAMEPLAY):number{if(!Number.isFinite(distance)||distance<0||distance>=config.burstRange)return 0;return config.burstForce*Math.max(.25,1-distance/(config.burstRange*1.15))}export function isPerfectDash(dashActive:number,alreadyConsumed:boolean,distance:number,contactDistance:number):boolean{return dashActive>0&&!alreadyConsumed&&Number.isFinite(distance)&&distance<=contactDistance+3}
