import type{GameplayConfig,NormalizedInput}from'../../types/game.js';import{GAMEPLAY}from'../config.js';export const clamp=(value:number,min:number,max:number):number=>Math.max(min,Math.min(max,Number.isFinite(value)?value:min));export function normalizeInput(x:number,y:number,sensitivity=1):NormalizedInput{const sx=Number.isFinite(x)?x:0,sy=Number.isFinite(y)?y:0,magnitude=Math.hypot(sx,sy);if(magnitude<=.0001)return{x:0,y:0,magnitude:0};const scaledMagnitude=clamp(magnitude*clamp(sensitivity,.6,1.5),0,1);return{x:sx/magnitude*scaledMagnitude,y:sy/magnitude*scaledMagnitude,magnitude:scaledMagnitude}}export function applyDeadzone(value:number,deadzone=GAMEPLAY.controllerDeadzone):number{const v=clamp(Number(value)||0,-1,1),a=Math.abs(v);if(a<=deadzone)return 0;return Math.sign(v)*(a-deadzone)/(1-deadzone)}export function stepMovement(vx:number,vy:number,inputX:number,inputY:number,dt:number,config:GameplayConfig=GAMEPLAY):{vx:number;vy:number}{const frame=clamp(dt*60,0,2),input=normalizeInput(inputX,inputY,1);let outX=Number.isFinite(vx)?vx:0,outY=Number.isFinite(vy)?vy:0;if(input.magnitude>.001){outX+=input.x*config.playerAcceleration*frame;outY+=input.y*config.playerAcceleration*frame;const friction=Math.pow(config.playerMovingFriction,frame);outX*=friction;outY*=friction}else{const friction=Math.pow(config.playerIdleFriction,frame);outX*=friction;outY*=friction}const speed=Math.hypot(outX,outY);if(speed>config.playerMaxSpeed){outX=outX/speed*config.playerMaxSpeed;outY=outY/speed*config.playerMaxSpeed}if(Math.abs(outX)<.003)outX=0;if(Math.abs(outY)<.003)outY=0;return{vx:outX,vy:outY}}export function physicsSubsteps(vx:number,vy:number,dt:number,config:GameplayConfig=GAMEPLAY):number{const travel=Math.hypot(Number(vx)||0,Number(vy)||0)*clamp(dt*60,0,2);return clamp(Math.ceil(travel/config.substepTravel),1,config.maxSubsteps)}export function bounceVelocity(velocity:number,restitution=GAMEPLAY.wallRestitution):number{const value=Number.isFinite(velocity)?velocity:0;return value===0?0:-value*clamp(restitution,0,1)}
