import type{BallEntity}from'../../types/game.js';import{ARENA}from'../config.js';export interface GoalBounds{top:number;bottom:number;leftLine:number}export function goalBounds(height:number):GoalBounds{return{top:height/2-ARENA.goalHalfHeight,bottom:height/2+ARENA.goalHalfHeight,leftLine:ARENA.wall}}export function isBallInsideGoal(ball:Pick<BallEntity,'x'|'y'|'r'>,width:number,height:number):'left'|'right'|null{if(!Number.isFinite(ball.x)||!Number.isFinite(ball.y)||!Number.isFinite(ball.r))return null;const bounds=goalBounds(height);if(!(ball.y>bounds.top&&ball.y<bounds.bottom))return null;if(ball.x-ball.r<=bounds.leftLine)return'left';if(ball.x+ball.r>=width-bounds.leftLine)return'right';return null}export const shouldEnterOvertime=(timeRemaining:number,scoreA:number,scoreB:number):boolean=>timeRemaining<=0&&scoreA===scoreB;
